INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('hash:1ff7623bbe9278868595f3746149104260d333f22752e7229284549557de71c7', '2026-Q3', 'Set/2026 (T3)', '2026-09-29T12:06'::timestamptz, 'Alessandra Girotto', 'alessandra girotto', 'PHARUS', 'Gustavo Papeschi Mariano', 10.0, 'Promotor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Para mim, esse cuidado próximo e humanizado, aliado à percepção de que tenho espaço para evoluir e construir meu patrimônio de forma mais estruturada, é um dos principais diferenciais da experiência com a Quarta Via.', NULL, 'O que mais contribui para a minha percepção positiva é a proximidade e a constância do acompanhamento da equipe. Considero especialmente positivo ter profissionais que me procuram regularmente para entender como estou e me ajudar a organizar melhor minha vida financeira, trazendo direcionamento e mais clareza para as minhas decisões. É um tipo de suporte que eu nunca havia vivenciado em outros serviços.', 'Disciplina e acompanhamento, além dos resultados esperados.', 'Não, já é o bastante', NULL, NULL, 'cadastro oficial', 'cadastro_NPS_2026-T3_PHARUS_atual.csv', 'cadastro (ciclo vigente)', NULL, 'cadastro oficial (Programa = PHARUS)', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
