INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('hash:0d085987677ab3067daee008f6ffad4376093efb0de2f802357d048eff1aa922', '2026-Q3', 'Set/2026 (T3)', '2026-09-29T19:49'::timestamptz, 'Leandro Antonio de Oliveira Correia', 'leandro antonio de oliveira correia', 'PHARUS', 'Gabriel Oliveira', 3.0, 'Detrator', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Não indico a Quarta via por que as pessoas no meu convívio e sócios não tem a maturidade,  nem a mentalidade, nem o conhecimento de educação financeira adequado para valorar, compreender e executar a metodologia de maneira efetiva, portanto em função desse fato não recomendo. Assim que a minha rede de contatos for mais aderente a metodologia posso recomenda-los.', 'Sei que não é o foco e nem o perfil de clientes mas seria interessante que ao identificar que o cliente possui a renda mensal dentro do esperado, mas não possui a mentalidade adequada ou educação financeira mínima  que fosse feito um acompanhamento mais próximo a esse cliente para identificar se a mentalidade do mesmo esta adequada para dar continuidade no programa ou não, caso exista aderência um acompanhamento semanal seria de grande valia para acelerar a curva de aprendizado do cliente.', NULL, 'Resultados.', 'Desruptura total, eu e minha esposa estamos acendendo financeiramente e tudo que construimos foi sem orientação, na raça e na coragem. Com a técnica da Quarta Via estamos depurando os nossos conhecimentos e mudando rotas erradas que tomamos por falta de conhecimento e suporte. A jornada está árdua mas muito recompensadora. Estamos no caminho correto.', NULL, NULL, 'cadastro oficial', 'cadastro_NPS_2026-T3_PHARUS_atual.csv', 'cadastro (ciclo vigente)', NULL, 'cadastro oficial (Programa = PHARUS)', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
