INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('hash:9042c901eb82dbb7df826eb319ea004a5b9fe7b91834f82d48b264dc8cd7c0bd', '2026-Q3', 'Set/2026 (T3)', '2026-09-30T18:42'::timestamptz, 'Yasmin Allgayer Sobé', 'yasmin allgayer sobe', 'PHARUS', 'Thiago Henrique Trova', 10.0, 'Promotor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Acho o trabalho de vocês bem incrível!', NULL, 'O formato é bom, a entrega funciona, todas as minhas dúvidas e inseguranças sobre contratos e afins foram sanadas.', 'Eu bater as minhas metas de investimentos e o que planejamentos neste primeiro ano.', 'Vocês são realmente muito bons! Meus pontos de atenção e chatice são pq eu trabalho com diversos tipos de infoprodutores, crio ecossistemas digitais e entendo da parte ruim desse mercado. Mas em resumo gosto de como estamos caminhando no projeto.', NULL, NULL, 'cadastro oficial', 'cadastro_NPS_2026-T3_PHARUS_atual.csv', 'cadastro (ciclo vigente)', NULL, 'cadastro oficial (Programa = PHARUS)', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
